import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

kl_div_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void kl_div_forward_kernel(const float* __restrict__ preds,
                                      const float* __restrict__ tgts,
                                      float* __restrict__ partial_sums,
                                      int N,
                                      int batch_size) {
    __shared__ float sdata[256];
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float tmp = 0.f;

    // Loop over elements assigned to this thread
    while (idx < N) {
        float p = fmaxf(preds[idx], 1e-12f);
        float t = fmaxf(tgts[idx], 1e-12f);
        tmp += t * (logf(t) - logf(p));
        idx += blockDim.x * gridDim.x;
    }

    // Store intermediate sum in shared memory
    sdata[threadIdx.x] = tmp;
    __syncthreads();

    // Block-level reduction
    for(int stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if(threadIdx.x < stride) {
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // Write result for this block
    if(threadIdx.x == 0) {
        partial_sums[blockIdx.x] = sdata[0];
    }
}

torch::Tensor kl_div_cuda(torch::Tensor predictions, torch::Tensor targets) {
    auto preds = predictions.contiguous();
    auto tgts = targets.contiguous();
    int64_t N = preds.numel();
    int64_t batch_size = preds.size(0);

    auto options = torch::TensorOptions().dtype(preds.dtype()).device(preds.device());

    const int block_size = 256;
    const int grid_size = (N + block_size - 1) / block_size;

    // Allocate partial sums for each block
    torch::Tensor partial_sums = torch::zeros({grid_size}, options);

    // Launch kernel
    kl_div_forward_kernel<<<grid_size, block_size>>>(
        preds.data_ptr<float>(),
        tgts.data_ptr<float>(),
        partial_sums.data_ptr<float>(),
        N,
        batch_size
    );

    // Sum on the CPU
    float total = partial_sums.sum().item<float>();
    total /= static_cast<float>(batch_size);

    // Return a single scalar tensor
    torch::Tensor out = torch::empty({}, options);
    out.fill_(total);
    return out;
}
"""

kl_div_cpp_source = r"""
torch::Tensor kl_div_cuda(torch::Tensor predictions, torch::Tensor targets);
"""

kl_div_module = load_inline(
    name="kl_div_module",
    cpp_sources=kl_div_cpp_source,
    cuda_sources=kl_div_cuda_source,
    functions=["kl_div_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    A model that computes Kullback-Leibler Divergence for comparing two distributions
    using a fused custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.kl_div = kl_div_module

    def forward(self, predictions, targets):
        return self.kl_div.kl_div_cuda(predictions, targets)
